import {
  Component, DestroyRef, ElementRef, NgZone, afterNextRender, computed, effect, inject, input, linkedSignal, model, output, signal, viewChild,
} from '@angular/core';
import { NgTemplateOutlet } from '@angular/common';
import {
  TablerIconComponent, IconPlus, IconMinus, IconZoomIn, IconZoomOut,
  IconArrowsMaximize, IconLayoutDistributeVertical, IconLayoutDistributeHorizontal,
  IconArrowsMoveVertical, IconSearch, IconX, IconChevronLeft, IconChevronRight, IconHome,
  IconUser, IconBriefcase, IconBuilding, IconDotsVertical,
} from '@tabler/icons-angular';

export type HrmOrgOrientation = 'vertical' | 'horizontal';
/** Chế độ xem đổi trọng tâm thẻ: nhân viên / chức vụ / phòng ban. */
export type HrmOrgViewMode = 'employee' | 'position' | 'department';

/** Một node trong sơ đồ tổ chức. */
export interface HrmOrgNode {
  id: string;
  name: string;
  /** Chức danh. */
  title?: string;
  /** URL ảnh; bỏ trống dùng chữ viết tắt. */
  avatar?: string;
  /** Chữ viết tắt (bỏ trống tự suy từ name). */
  initials?: string;
  /** Dòng phụ: phòng ban / mã NV… */
  meta?: string;
  /** Badge góc phải (VD số nhân viên dưới quyền). */
  badge?: string | number;
  /** id các node báo cáo chấm (dotted / ma trận) — vẽ đường nét đứt. */
  dottedReports?: string[];
  /** Gập sẵn nhánh con. */
  collapsed?: boolean;
  children?: HrmOrgNode[];

  // --- Chế độ Phòng ban (department) ---
  /** Tên đơn vị node đứng đầu (Tập đoàn / Khối / Đơn vị / Phòng ban). */
  unit?: string;
  /** Quân số của đơn vị. */
  headcount?: number;

  // --- Chế độ Vị trí (position) ---
  /** Tên vị trí (VD "Trưởng phòng"). */
  position?: string;
  /** Số đang đảm nhiệm / tổng biên chế → "5/6". */
  filled?: number;
  slots?: number;
  /** Số đang tuyển (badge Hiring). */
  hiring?: number;
  /** Cơ cấu loại hợp đồng: [{ type:'FTE', count:1 }, …]. */
  breakdown?: { type: string; count: number }[];
  /** Nhân viên đang đảm nhiệm vị trí này. */
  holders?: HrmOrgHolder[];
}

/** Nhân viên đảm nhiệm 1 vị trí (chế độ Vị trí). */
export interface HrmOrgHolder {
  name: string;
  avatar?: string;
  initials?: string;
  /** Loại hợp đồng (FTE / PTE / INT…). */
  type?: string;
  /** Phòng ban. */
  dept?: string;
}

/** Nhãn a11y thanh công cụ + chú thích (i18n — bên gọi cấp; bỏ trống = không aria-label). */
export interface HrmOrgLabels {
  vertical?: string;
  horizontal?: string;
  compact?: string;
  expandAll?: string;
  collapseAll?: string;
  zoomIn?: string;
  zoomOut?: string;
  fit?: string;
  /** Placeholder ô tìm nhân sự. */
  search?: string;
  prevMatch?: string;
  nextMatch?: string;
  /** Nút về gốc (thoát chế độ focus nhánh). */
  home?: string;
  /** Chú thích legend: đường báo cáo trực tiếp / báo cáo chấm. */
  directLine?: string;
  dottedLine?: string;
  /** Nhãn nút chế độ xem. */
  modeEmployee?: string;
  modePosition?: string;
  modeDepartment?: string;
  /** Hậu tố quân số đơn vị (VD "nhân viên" → "23 nhân viên"). */
  employees?: string;
  /** Nhãn badge đang tuyển (VD "Hiring" → "1 Hiring"). */
  hiring?: string;
  /** Hậu tố nút "+N …" khi quá 5 holder (VD "nhân viên khác"). */
  moreHolders?: string;
  /** Nhãn a11y nút "⋮" chứa các nhóm nút bị thu gọn khi thanh công cụ hẹp. */
  more?: string;
}

interface Laid {
  node: HrmOrgNode;
  x: number; y: number; w: number; h: number; depth: number;
  hasKids: boolean; open: boolean; count: number;
}
interface Edge { d: string; from: string; to: string; }
interface OrgView {
  nodes: Laid[]; edges: Edge[]; dotted: Edge[];
  w: number; h: number; nw: number; nh: number;
}

/** hrm-org-chart — sơ đồ tổ chức: node dạng thẻ (avatar + tên + chức danh + phòng ban),
 *  đường báo cáo trực tiếp (nét liền) và báo cáo chấm/ma trận (nét đứt). Nhiều chế độ xem:
 *  hướng dọc/ngang, thu gọn, gập/mở từng nhánh hoặc toàn bộ, kéo-pan + phóng-to/nhỏ.
 *  Toàn token → tự bám Light/Dark/brand. Text hiển thị = data caller cấp; nhãn nút = [labels] (i18n).
 *  <hrm-org-chart [data]="root" [(orientation)]="dir" [(selectedId)]="sel" (nodeClick)="..." [labels]="lbl" /> */
@Component({
  selector: 'hrm-org-chart',
  imports: [TablerIconComponent, NgTemplateOutlet],
  template: `
    <div class="oc" [class.oc--h]="orientation() === 'horizontal'">
      @if (showToolbar()) {
        <div class="oc-toolbar" [class.oc-toolbar--tight]="tight()" #toolbar>
          @if (showModes()) {
            <div class="oc-tb-grp oc-tb-modes" data-grp="modes">
              <button type="button" class="oc-tb-btn oc-tb-wide" [class.is-on]="viewMode() === 'department'"
                (click)="viewMode.set('department')" [attr.aria-label]="labels().modeDepartment || null">
                <tabler-icon [icon]="$any(deptIcon)" [size]="16" />
                @if (labels().modeDepartment) { <span class="oc-tb-lbl">{{ labels().modeDepartment }}</span> }
              </button>
              <button type="button" class="oc-tb-btn oc-tb-wide" [class.is-on]="viewMode() === 'position'"
                (click)="viewMode.set('position')" [attr.aria-label]="labels().modePosition || null">
                <tabler-icon [icon]="$any(posIcon)" [size]="16" />
                @if (labels().modePosition) { <span class="oc-tb-lbl">{{ labels().modePosition }}</span> }
              </button>
              <button type="button" class="oc-tb-btn oc-tb-wide" [class.is-on]="viewMode() === 'employee'"
                (click)="viewMode.set('employee')" [attr.aria-label]="labels().modeEmployee || null">
                <tabler-icon [icon]="$any(empIcon)" [size]="16" />
                @if (labels().modeEmployee) { <span class="oc-tb-lbl">{{ labels().modeEmployee }}</span> }
              </button>
            </div>
          }

          <!-- Nhóm phụ — thu gọn dần vào "⋮" khi hẹp (thứ tự mất: orientation → công cụ → zoom). -->
          @if (!isHidden('orient')) { <div class="oc-tb-grp" data-grp="orient"><ng-container *ngTemplateOutlet="tbOrient" /></div> }
          @if (!isHidden('tools'))  { <div class="oc-tb-grp" data-grp="tools"><ng-container *ngTemplateOutlet="tbTools" /></div> }
          @if (!isHidden('zoom'))   { <div class="oc-tb-grp" data-grp="zoom"><ng-container *ngTemplateOutlet="tbZoom" /></div> }

          @if (focusable() && focusId()) {
            <button type="button" class="oc-tb-btn oc-tb-solo" (click)="resetFocus()" [attr.aria-label]="labels().home || null">
              <tabler-icon [icon]="$any(homeIcon)" [size]="18" />
            </button>
          }

          <!-- Nút "⋮" — chứa các nhóm đã thu gọn (theo đúng thứ tự). -->
          @if (hidden().length) {
            <div class="oc-more">
              <button type="button" class="oc-tb-btn oc-more-btn" [class.is-on]="moreOpen()"
                (click)="toggleMore($event)" aria-haspopup="menu" [attr.aria-expanded]="moreOpen()"
                [attr.aria-label]="labels().more || null">
                <tabler-icon [icon]="$any(moreIcon)" [size]="18" />
              </button>
              @if (moreOpen()) {
                <div class="oc-more-menu" role="menu">
                  @if (isHidden('orient')) { <div class="oc-more-grp"><ng-container *ngTemplateOutlet="tbOrient" /></div> }
                  @if (isHidden('tools'))  { <div class="oc-more-grp"><ng-container *ngTemplateOutlet="tbTools" /></div> }
                  @if (isHidden('zoom'))   { <div class="oc-more-grp"><ng-container *ngTemplateOutlet="tbZoom" /></div> }
                </div>
              }
            </div>
          }

          @if (searchable()) {
            <div class="oc-search" data-grp="search">
              <tabler-icon class="oc-search-ic" [icon]="$any(searchIcon)" [size]="16" />
              <input class="oc-search-in" type="text" [value]="searchQuery()" (input)="onSearch($event)"
                (keydown.enter)="nextMatch()" [attr.placeholder]="labels().search || null" [attr.aria-label]="labels().search || null" />
              @if (searchQuery()) {
                <span class="oc-search-n">{{ matchIds().length ? (matchIdx() + 1) + '/' + matchIds().length : '0' }}</span>
                <button type="button" class="oc-search-b" (click)="prevMatch()" [disabled]="!matchIds().length" [attr.aria-label]="labels().prevMatch || null">
                  <tabler-icon [icon]="$any(prevIcon)" [size]="14" />
                </button>
                <button type="button" class="oc-search-b" (click)="nextMatch()" [disabled]="!matchIds().length" [attr.aria-label]="labels().nextMatch || null">
                  <tabler-icon [icon]="$any(nextIcon)" [size]="14" />
                </button>
                <button type="button" class="oc-search-b" (click)="clearSearch()"><tabler-icon [icon]="$any(clearIcon)" [size]="14" /></button>
              }
            </div>
          }
        </div>

        <!-- Nhóm nút dùng chung: render inline (trong thanh) hoặc trong menu "⋮". -->
        <ng-template #tbOrient>
          <button type="button" class="oc-tb-btn" [class.is-on]="orientation() === 'vertical'"
            (click)="orientation.set('vertical')" [attr.aria-label]="labels().vertical || null">
            <tabler-icon [icon]="$any(vIcon)" [size]="18" />
          </button>
          <button type="button" class="oc-tb-btn" [class.is-on]="orientation() === 'horizontal'"
            (click)="orientation.set('horizontal')" [attr.aria-label]="labels().horizontal || null">
            <tabler-icon [icon]="$any(hIcon)" [size]="18" />
          </button>
        </ng-template>
        <ng-template #tbTools>
          <button type="button" class="oc-tb-btn" [class.is-on]="compact()"
            (click)="compact.set(!compact())" [attr.aria-label]="labels().compact || null">
            <tabler-icon [icon]="$any(compactIcon)" [size]="18" />
          </button>
          <button type="button" class="oc-tb-btn" (click)="expandAll()" [attr.aria-label]="labels().expandAll || null">
            <tabler-icon [icon]="$any(plusIcon)" [size]="18" />
          </button>
          <button type="button" class="oc-tb-btn" (click)="collapseAll()" [attr.aria-label]="labels().collapseAll || null">
            <tabler-icon [icon]="$any(minusIcon)" [size]="18" />
          </button>
        </ng-template>
        <ng-template #tbZoom>
          <button type="button" class="oc-tb-btn" (click)="zoomBy(0.9)" [attr.aria-label]="labels().zoomOut || null">
            <tabler-icon [icon]="$any(zoomOutIcon)" [size]="18" />
          </button>
          <button type="button" class="oc-tb-btn" (click)="fit()" [attr.aria-label]="labels().fit || null">
            <tabler-icon [icon]="$any(fitIcon)" [size]="18" />
          </button>
          <button type="button" class="oc-tb-btn" (click)="zoomBy(1.1)" [attr.aria-label]="labels().zoomIn || null">
            <tabler-icon [icon]="$any(zoomInIcon)" [size]="18" />
          </button>
        </ng-template>
      }

      <div class="oc-viewport" #vp
        (pointerdown)="onDown($event)" (pointermove)="onMove($event)"
        (pointerup)="onUp($event)" (pointerleave)="onUp($event)" (wheel)="onWheel($event)">
        <!-- Chú thích (legend) — nổi góc TRÊN-PHẢI trong canvas. -->
        @if (showLegend()) {
          <div class="oc-legend">
            <span class="oc-lg"><span class="oc-lg-ln"></span>{{ labels().directLine }}</span>
            <span class="oc-lg"><span class="oc-lg-ln oc-lg-ln--dot"></span>{{ labels().dottedLine }}</span>
          </div>
        }
        <div class="oc-canvas" [style.width.px]="view().w" [style.height.px]="view().h"
          [style.transform]="'translate(' + pan().x + 'px,' + pan().y + 'px) scale(' + zoom() + ')'"
          [style.transition]="dragging() ? 'none' : 'transform .34s cubic-bezier(.22,.61,.36,1)'">

          <svg class="oc-lines" [attr.width]="view().w" [attr.height]="view().h">
            @for (e of view().edges; track $index) {
              <path [attr.d]="e.d" class="oc-edge" [class.is-dim]="isEdgeDim(e)" [class.is-lit]="isEdgeLit(e)" />
            }
            @for (e of view().dotted; track $index) {
              @if (isDottedLit(e)) {
                <path [attr.d]="e.d" class="oc-edge oc-edge--dotted is-lit" />
              }
            }
          </svg>

          @for (n of view().nodes; track n.node.id) {
            <div class="oc-node oc-node--{{ viewMode() }}" [class.is-active]="n.node.id === selectedId()"
              [class.is-match]="isMatch(n.node.id)" [class.is-current]="n.node.id === currentMatchId()"
              [class.is-dim]="isDim(n.node.id)"
              [style.left.px]="n.x" [style.top.px]="n.y" [style.width.px]="n.w" [style.height.px]="n.h"
              (click)="pick(n.node)" (dblclick)="onDblNode(n.node)">

              @if (viewMode() === 'department' && n.node.unit) {
                <div class="oc-dept">
                  <div class="oc-dept-unit">
                    <span class="oc-unit-name">{{ n.node.unit }}</span>
                    <span class="oc-unit-sub">{{ headcountText(n.node) }}</span>
                  </div>
                  <div class="oc-dept-head">
                    <span class="oc-av" [attr.data-hue]="n.node.avatar ? null : avatarHue(n.node.name)">
                      @if (n.node.avatar) { <img [src]="n.node.avatar" alt="" /> }
                      @else { {{ n.node.initials || initialsOf(n.node.name) }} }
                    </span>
                    <span class="oc-body">
                      <span class="oc-name">{{ n.node.name }}</span>
                      @if (n.node.title) { <span class="oc-title">{{ n.node.title }}</span> }
                    </span>
                  </div>
                </div>
              } @else if (viewMode() === 'position' && n.node.position) {
                <div class="oc-pos">
                  <div class="oc-pos-h">
                    <div class="oc-pos-title">{{ n.node.position }}</div>
                    @if (n.node.filled != null) {
                      <div class="oc-pos-count">{{ n.node.filled }}/{{ n.node.slots ?? n.node.filled }}
                        @if (breakdownText(n.node)) { <span class="oc-pos-bd">({{ breakdownText(n.node) }})</span> }
                      </div>
                    }
                    @if (n.node.hiring) { <span class="oc-pos-hire">{{ n.node.hiring }} {{ labels().hiring }}</span> }
                  </div>
                  <div class="oc-pos-list">
                    @for (h of holdersShown(n.node); track $index) {
                      <div class="oc-pos-row">
                        <span class="oc-av oc-av--sm" [attr.data-hue]="h.avatar ? null : avatarHue(h.name)">
                          @if (h.avatar) { <img [src]="h.avatar" alt="" /> } @else { {{ h.initials || initialsOf(h.name) }} }
                        </span>
                        <span class="oc-pos-info">
                          <span class="oc-pos-hn"><span class="oc-pos-nm">{{ h.name }}</span>@if (h.type) { <span class="oc-pos-tag">{{ h.type }}</span> }</span>
                          @if (h.dept) { <span class="oc-pos-hd">{{ h.dept }}</span> }
                        </span>
                      </div>
                    }
                    @if (holdersMore(n.node) > 0) {
                      <button type="button" class="oc-pos-more" (click)="$event.stopPropagation()">+{{ holdersMore(n.node) }} {{ labels().moreHolders }}</button>
                    }
                  </div>
                </div>
              } @else {
                <span class="oc-av" [attr.data-hue]="n.node.avatar ? null : avatarHue(n.node.name)">
                  @if (n.node.avatar) { <img [src]="n.node.avatar" alt="" /> }
                  @else { {{ n.node.initials || initialsOf(n.node.name) }} }
                </span>
                <span class="oc-body">
                  <span class="oc-name">{{ n.node.name }}</span>
                  @if (n.node.title) { <span class="oc-title">{{ n.node.title }}</span> }
                  @if (n.node.meta && !compact()) { <span class="oc-meta">{{ n.node.meta }}</span> }
                </span>
                @if (viewMode() === 'employee' && badgeOf(n) != null) { <span class="oc-badge">{{ badgeOf(n) }}</span> }
              }

              @if (n.hasKids) {
                <button type="button" class="oc-toggle" [class.oc-toggle--h]="orientation() === 'horizontal'"
                  (click)="$event.stopPropagation(); toggle(n.node.id)"
                  [attr.aria-label]="(n.open ? labels().collapseAll : labels().expandAll) || null">
                  <tabler-icon [icon]="$any(n.open ? minusIcon : plusIcon)" [size]="14" />
                </button>
              }
            </div>
          }
        </div>
      </div>
    </div>
  `,
  host: { class: 'hrm-org-chart', '(window:resize)': 'reflow()' },
  styles: [`
:host { display: block; }
.oc { display: flex; flex-direction: column; gap: 10px; font-family: var(--font-sans); }

/* Toolbar hợp nhất — 1 thanh nền trắng, bo góc theo token. Các nhóm nút + ô tìm cùng nằm trong.
   Ngăn cách nhóm bằng đường mảnh thay vì pill riêng. */
.oc-toolbar {
  display: flex; align-items: center; gap: 4px; flex-wrap: nowrap; min-width: 0;
  padding: 4px; box-sizing: border-box;
  background: var(--bg-surface); border: 1px solid var(--border-sub); border-radius: var(--radius-lg);
}
.oc-tb-grp {
  display: inline-flex; padding: 0; gap: 2px;
  background: transparent; border: 0; border-radius: 0;
}
/* Đường ngăn cách giữa các nhóm nút trong cùng thanh. */
.oc-tb-grp + .oc-tb-grp { margin-left: 4px; padding-left: 6px; border-left: 1px solid var(--border-soft, var(--border-sub)); }
.oc-tb-btn {
  display: grid; place-items: center; width: 32px; height: 32px; padding: 0; box-sizing: border-box;
  border: 0; background: transparent; cursor: pointer; color: var(--text-sub);
  border-radius: var(--radius-md); transition: background var(--duration-fast, .15s) var(--ease-out, ease);
}
.oc-tb-btn:hover { background: var(--bg-surface-subtle); color: var(--text-strong); }
.oc-tb-btn.is-on { background: var(--primary-bg-subtle); color: var(--primary-base); box-shadow: none; }
.oc-tb-wide { display: inline-flex; align-items: center; justify-content: center; width: auto; gap: 6px; padding: 0 12px; height: 32px; }
.oc-tb-lbl { font-size: var(--fs-13); font-weight: 500; white-space: nowrap; }
/* Rất hẹp → nút chế độ xem chỉ còn icon (bỏ nhãn) để nhường chỗ cho ô tìm bên phải. */
.oc-toolbar--tight .oc-tb-wide { width: 32px; padding: 0; gap: 0; }
.oc-toolbar--tight .oc-tb-lbl { display: none; }

/* Nút "⋮" + menu chứa nhóm nút bị thu gọn khi thanh công cụ hẹp. */
.oc-more { position: relative; display: inline-flex; flex: none; }
.oc-tb-grp + .oc-more { margin-left: 4px; padding-left: 6px; border-left: 1px solid var(--border-soft, var(--border-sub)); }
.oc-more-btn.is-on { background: var(--primary-bg-subtle); color: var(--primary-base); }
.oc-more-menu {
  position: absolute; top: calc(100% + 6px); right: 0; z-index: 30;
  display: flex; flex-direction: column; gap: 4px; padding: 6px;
  background: var(--bg-surface); border: 1px solid var(--border-sub);
  border-radius: var(--radius-lg); box-shadow: var(--shadow-regular-md);
}
.oc-more-grp { display: inline-flex; gap: 2px; }
.oc-more-grp + .oc-more-grp { margin-top: 4px; padding-top: 4px; border-top: 1px solid var(--border-soft, var(--border-sub)); }

.oc-viewport {
  position: relative; overflow: hidden; touch-action: none; cursor: grab;
  height: var(--org-height, 480px);
  /* Nền canvas ĐẬM hơn 1 chút để tách khỏi nền page content. */
  background: color-mix(in srgb, var(--bg-surface-subtle) 78%, var(--border-strong, var(--border-sub)));
  border: 1px solid var(--border-sub); border-radius: var(--radius-xl);
  background-image: radial-gradient(var(--border-strong, var(--border-sub)) 1px, transparent 1px); background-size: 22px 22px;
}
.oc-viewport:active { cursor: grabbing; }
.oc-canvas { position: absolute; top: 0; left: 0; transform-origin: 0 0; }
.oc-lines { position: absolute; top: 0; left: 0; overflow: visible; pointer-events: none; }
.oc-edge { fill: none; stroke: var(--border-strong, var(--border-sub)); stroke-width: 1.5; }
.oc-edge--dotted { stroke: var(--primary-base); stroke-dasharray: 4 4; opacity: .7; }

.oc-node {
  position: absolute; display: flex; align-items: center; gap: 10px; box-sizing: border-box;
  padding: 10px 12px; background: var(--bg-surface);
  border: 1px solid var(--border-sub); border-radius: var(--radius-lg); box-shadow: var(--shadow-regular-xs);
  cursor: pointer; transition: border-color var(--duration-fast, .15s) var(--ease-out, ease), box-shadow var(--duration-fast, .15s) var(--ease-out, ease);
}
.oc-node:hover { border-color: var(--primary-border, var(--primary-base)); box-shadow: var(--shadow-regular-sm); }
.oc-node.is-active { border-color: var(--primary-base); box-shadow: 0 0 0 3px var(--primary-bg-subtle); }
.oc-av {
  flex: none; display: grid; place-items: center; width: 40px; height: 40px; border-radius: 50%;
  overflow: hidden; background: var(--primary-base); color: var(--text-on-primary, #fff); font-size: var(--fs-14); font-weight: 600;
}
.oc-av img { width: 100%; height: 100%; object-fit: cover; }
/* Avatar chữ: 8 màu hue theo tên (đồng bộ hrm-avatar) */
.oc-av[data-hue="0"] { background: var(--blue-600); }
.oc-av[data-hue="1"] { background: var(--green-600); }
.oc-av[data-hue="2"] { background: var(--amber-600); }
.oc-av[data-hue="3"] { background: var(--red-600); }
.oc-av[data-hue="4"] { background: var(--purple-600); }
.oc-av[data-hue="5"] { background: var(--teal-600); }
.oc-av[data-hue="6"] { background: var(--cyan-600); }
.oc-av[data-hue="7"] { background: var(--pink-600); }
.oc-body { flex: 1; min-width: 0; display: flex; flex-direction: column; gap: 1px; }
.oc-name { font-size: var(--fs-14); font-weight: 600; color: var(--text-strong); white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
.oc-title { font-size: var(--fs-12); color: var(--text-sub); white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
.oc-meta { font-size: var(--fs-11); color: var(--text-soft); white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
.oc-badge {
  flex: none; align-self: flex-start; font-size: var(--fs-11); font-weight: 600; line-height: 1;
  padding: 3px 7px; border-radius: var(--radius-full); background: var(--primary-bg-soft); color: var(--primary-base);
}
.oc-toggle {
  position: absolute; left: 50%; bottom: -11px; transform: translateX(-50%);
  display: grid; place-items: center; width: 22px; height: 22px; padding: 0; z-index: 2;
  border: 1px solid var(--border-sub); background: var(--bg-surface); color: var(--text-sub);
  border-radius: 50%; cursor: pointer; box-shadow: var(--shadow-regular-xs);
}
.oc-toggle:hover { color: var(--primary-base); border-color: var(--primary-base); }
.oc-toggle--h { left: auto; bottom: auto; right: -11px; top: 50%; transform: translateY(-50%); }

/* Nút lẻ (Home) — nằm trong thanh trắng, cao 32px như các nút khác. */
.oc-tb-solo {
  width: 32px; height: 32px; border: 0; border-radius: var(--radius-md);
  background: transparent; color: var(--text-sub);
}
.oc-tb-solo:hover { background: var(--bg-surface-subtle); color: var(--text-strong); }

/* Ô tìm nhân sự — cao 32px BẰNG các nút; LUÔN ghim bên phải (margin-left:auto) trong thanh
   toolbar. Khi hẹp → CO LẠI (flex-shrink) thay vì tràn ra ngoài mép phải. */
.oc-search {
  display: inline-flex; align-items: center; gap: 6px; margin-left: auto; box-sizing: border-box;
  flex: 0 1 auto; min-width: 84px;
  height: 32px; padding: 0 10px;
  background: var(--bg-surface-subtle); border: 1px solid var(--border-sub); border-radius: var(--radius-md);
}
.oc-search:focus-within { border-color: var(--primary-base); }
.oc-search-ic { flex: none; color: var(--text-soft); }
.oc-search-in { flex: 1; min-width: 0; border: 0; background: transparent; outline: none; font-family: inherit; font-size: var(--fs-13); color: var(--text-body); }
.oc-search-in::placeholder { color: var(--text-soft); }
.oc-search-n { flex: none; font-size: var(--fs-12); color: var(--text-soft); font-variant-numeric: tabular-nums; }
.oc-search-b { flex: none; display: grid; place-items: center; width: 20px; height: 20px; padding: 0; border: 0; background: transparent; cursor: pointer; color: var(--text-sub); border-radius: var(--radius-sm); }
.oc-search-b:hover:not(:disabled) { color: var(--text-strong); background: var(--bg-surface); }
.oc-search-b:disabled { color: var(--text-disabled); cursor: not-allowed; }

/* Legend — nổi góc TRÊN-PHẢI trong canvas (không bị pan/zoom). */
.oc-legend {
  position: absolute; top: 10px; right: 10px; z-index: 4;
  display: flex; gap: 14px; padding: 6px 10px;
  background: color-mix(in srgb, var(--bg-surface) 88%, transparent);
  border: 1px solid var(--border-sub); border-radius: var(--radius-md);
  box-shadow: var(--shadow-regular-xs); backdrop-filter: blur(4px);
}
.oc-lg { display: inline-flex; align-items: center; gap: 7px; font-size: var(--fs-12); color: var(--text-sub); }
.oc-lg-ln { width: 22px; height: 0; border-top: 1.5px solid var(--border-strong, var(--border-sub)); }
.oc-lg-ln--dot { border-top-style: dashed; border-top-color: var(--primary-base); }

/* Tô sáng tuyến báo cáo + kết quả tìm */
.oc-node.is-dim { opacity: .32; }
.oc-node.is-match { border-color: var(--warning-base, var(--primary-base)); box-shadow: 0 0 0 2px var(--warning-bg, var(--primary-bg-subtle)); }
.oc-node.is-current { border-color: var(--primary-base); box-shadow: 0 0 0 3px var(--primary-bg-subtle); }
.oc-edge.is-dim { opacity: .12; }
.oc-edge.is-lit { stroke: var(--primary-base); stroke-width: 2; }
.oc-edge--dotted.is-lit { opacity: 1; stroke-width: 2; }

/* Card Phòng ban (department) — tên đơn vị + quân số + người đứng đầu */
.oc-node--department { flex-direction: column; align-items: stretch; padding: 0; gap: 0; }
.oc-dept { display: flex; flex-direction: column; height: 100%; min-height: 0; }
.oc-dept-unit { display: flex; flex-direction: column; gap: 2px; padding: 12px 14px 10px; }
.oc-dept-head { display: flex; align-items: center; gap: 10px; flex: 1; min-height: 0; padding: 10px 14px; border-top: 1px solid var(--border-soft); }
.oc-unit-name { font-size: var(--fs-15); font-weight: 700; color: var(--text-strong); white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
.oc-unit-sub { font-size: var(--fs-12); color: var(--text-sub); }

/* Card Vị trí (position) — tên vị trí + biên chế + list nhân viên. overflow VISIBLE để nút ±  không bị cắt. */
.oc-node--position { flex-direction: column; align-items: stretch; padding: 12px; gap: 8px; }
.oc-pos { display: flex; flex-direction: column; gap: 8px; height: 100%; min-height: 0; }
.oc-pos-h { display: flex; flex-direction: column; gap: 3px; padding-bottom: 8px; border-bottom: 1px solid var(--border-soft); }
.oc-pos-title { font-size: var(--fs-15); font-weight: 700; color: var(--text-strong); }
.oc-pos-count { font-size: var(--fs-12); color: var(--text-sub); font-variant-numeric: tabular-nums; }
.oc-pos-bd { color: var(--text-soft); }
.oc-pos-hire { align-self: flex-start; margin-top: 3px; font-size: var(--fs-11); font-weight: 600; line-height: 1;
  padding: 4px 8px; border-radius: var(--radius-sm); background: var(--text-strong); color: var(--bg-surface); }
.oc-pos-list { display: flex; flex-direction: column; gap: 7px; flex-shrink: 0; }
.oc-av--sm { width: 28px; height: 28px; font-size: var(--fs-11); }
.oc-pos-row { display: flex; align-items: center; gap: 8px; }
.oc-pos-info { flex: 1; min-width: 0; display: flex; flex-direction: column; gap: 1px; }
.oc-pos-hn { display: flex; align-items: center; gap: 6px; font-size: var(--fs-13); font-weight: 500; color: var(--text-strong); }
.oc-pos-nm { min-width: 0; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
.oc-pos-tag { flex: none; font-size: var(--fs-10); font-weight: 600; line-height: 1; padding: 2px 5px; border-radius: var(--radius-xs);
  background: var(--bg-surface-subtle); color: var(--text-sub); border: 1px solid var(--border-soft); }
.oc-pos-hd { font-size: var(--fs-11); color: var(--text-soft); white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
.oc-pos-more { align-self: flex-start; margin-top: 2px; padding: 3px 6px; border: 0; background: transparent; cursor: pointer;
  font-family: inherit; font-size: var(--fs-12); font-weight: 500; color: var(--primary-base); border-radius: var(--radius-sm); }
.oc-pos-more:hover { background: var(--primary-bg-subtle); }
  `],
})
export class HrmOrgChart {
  /** Dữ liệu gốc — 1 node (1 gốc) hoặc mảng node (nhiều gốc). */
  readonly data = input<HrmOrgNode | HrmOrgNode[] | null>(null);
  /** Hướng sơ đồ. Two-way để thanh công cụ tự lật. */
  readonly orientation = model<HrmOrgOrientation>('vertical');
  /** Chế độ thu gọn (node nhỏ, khoảng cách hẹp). Two-way. */
  readonly compact = model(false);
  /** Node đang chọn. Two-way. */
  readonly selectedId = model<string>('');
  /** Hiện thanh công cụ (hướng / thu gọn / gập-mở / zoom). */
  readonly showToolbar = input(true);
  /** Cho phép kéo-pan + cuộn phóng to/nhỏ. */
  readonly zoomable = input(true);
  /** Nhãn a11y các nút thanh công cụ + legend (i18n). */
  readonly labels = input<HrmOrgLabels>({});
  /** Ô tìm nhân sự trên thanh công cụ (tên/chức danh → nổi bật + canh giữa). */
  readonly searchable = input(false);
  /** Tự hiện tổng quân số dưới quyền (khi node không tự cấp badge). */
  readonly showCounts = input(false);
  /** Cho phép bấm-đúp node để focus (xem riêng) 1 nhánh; nút Home về gốc. */
  readonly focusable = input(false);
  /** Bấm 1 node → làm mờ phần khác, tô sáng tuyến báo cáo lên gốc. */
  readonly highlightPath = input(false);
  /** Hiện chú thích (legend) loại đường báo cáo. */
  readonly showLegend = input(false);
  /** Chế độ xem — đổi trọng tâm thẻ. Two-way. */
  readonly viewMode = model<HrmOrgViewMode>('employee');
  /** Hiện nhóm nút chuyển chế độ xem (Phòng ban / Chức vụ / Nhân viên). */
  readonly showModes = input(false);
  /** Bấm vào node. */
  readonly nodeClick = output<HrmOrgNode>();
  /** Đổi node focus (drill) — id rỗng = về gốc đầy đủ. */
  readonly focusChange = output<string>();

  protected readonly vIcon = IconLayoutDistributeVertical;
  protected readonly hIcon = IconLayoutDistributeHorizontal;
  protected readonly compactIcon = IconArrowsMoveVertical;
  protected readonly plusIcon = IconPlus;
  protected readonly minusIcon = IconMinus;
  protected readonly zoomInIcon = IconZoomIn;
  protected readonly zoomOutIcon = IconZoomOut;
  protected readonly fitIcon = IconArrowsMaximize;
  protected readonly searchIcon = IconSearch;
  protected readonly clearIcon = IconX;
  protected readonly prevIcon = IconChevronLeft;
  protected readonly nextIcon = IconChevronRight;
  protected readonly homeIcon = IconHome;
  protected readonly empIcon = IconUser;
  protected readonly posIcon = IconBriefcase;
  protected readonly deptIcon = IconBuilding;

  protected readonly searchQuery = signal('');
  protected readonly matchIdx = signal(0);
  protected readonly focusId = signal('');
  protected readonly dragging = signal(false);

  private readonly vp = viewChild<ElementRef<HTMLElement>>('vp');
  protected readonly zoom = signal(1);
  protected readonly pan = signal({ x: 0, y: 0 });
  private drag: { x: number; y: number; px: number; py: number; moved: boolean } | null = null;
  private movedRecently = false;

  // ── Thanh công cụ co giãn: thu nhóm nút phụ vào "⋮" khi hẹp (KHÔNG rớt dòng) ──
  private readonly toolbarRef = viewChild<ElementRef<HTMLElement>>('toolbar');
  private readonly zone = inject(NgZone);
  protected readonly moreIcon = IconDotsVertical;
  /** Các nhóm nút đang bị thu vào "⋮" (theo đúng thứ tự mất dần). */
  protected readonly hidden = signal<string[]>([]);
  protected readonly moreOpen = signal(false);
  /** Rất hẹp: thu nhãn nút chế độ xem (Phòng ban/Vị trí/Nhân viên) → chỉ còn icon, nhường chỗ cho ô tìm. */
  protected readonly tight = signal(false);
  /** Thứ tự MẤT DẦN khi hẹp: orientation → công cụ (gập/mở) → zoom. Modes + search luôn hiện. */
  private readonly DROP = ['orient', 'tools', 'zoom'];
  private grpW: Record<string, number> = {};
  private measured = false;
  protected isHidden(k: string): boolean { return this.hidden().includes(k); }
  protected toggleMore(e: Event): void { e.stopPropagation(); this.moreOpen.update((v) => !v); }

  private readonly fullRoots = computed<HrmOrgNode[]>(() => {
    const d = this.data();
    return Array.isArray(d) ? d : d ? [d] : [];
  });
  protected readonly roots = computed<HrmOrgNode[]>(() => {
    const fid = this.focusId();
    if (fid) { const n = this.findNode(fid); if (n) return [n]; }
    return this.fullRoots();
  });
  private findNode(id: string): HrmOrgNode | null {
    const dfs = (n: HrmOrgNode): HrmOrgNode | null => {
      if (n.id === id) return n;
      for (const c of n.children ?? []) { const r = dfs(c); if (r) return r; }
      return null;
    };
    for (const r of this.fullRoots()) { const f = dfs(r); if (f) return f; }
    return null;
  }

  private readonly parentMap = computed<Map<string, string>>(() => {
    const m = new Map<string, string>();
    const walk = (n: HrmOrgNode, p?: string) => { if (p) m.set(n.id, p); n.children?.forEach((c) => walk(c, n.id)); };
    this.fullRoots().forEach((r) => walk(r));
    return m;
  });
  private readonly countMap = computed<Map<string, number>>(() => {
    const m = new Map<string, number>();
    const count = (n: HrmOrgNode): number => {
      let c = 0;
      for (const k of n.children ?? []) c += 1 + count(k);
      m.set(n.id, c);
      return c;
    };
    this.fullRoots().forEach(count);
    return m;
  });

  /** Tập id đang gập — seed từ node.collapsed, tự reset khi data/focus đổi; ghi được (toggle/all). */
  protected readonly collapsedSet = linkedSignal<Set<string>>(() => {
    const s = new Set<string>();
    const walk = (n: HrmOrgNode) => { if (n.collapsed) s.add(n.id); n.children?.forEach(walk); };
    this.roots().forEach(walk);
    return s;
  });

  constructor() {
    const destroyRef = inject(DestroyRef);
    afterNextRender(() => {
      this.fit();
      this.reflow();
      const tb = this.toolbarRef()?.nativeElement;
      if (tb && typeof ResizeObserver !== 'undefined') {
        const ro = new ResizeObserver(() => this.zone.run(() => this.reflow()));
        ro.observe(tb);
        destroyRef.onDestroy(() => ro.disconnect());
      }
      // Bấm ra ngoài → đóng menu "⋮".
      const onDoc = (e: Event) => { if (this.moreOpen() && tb && !tb.contains(e.target as Node)) this.moreOpen.set(false); };
      document.addEventListener('click', onDoc, true);
      destroyRef.onDestroy(() => document.removeEventListener('click', onDoc, true));
    });
    // Đổi nhãn / chế độ xem / bật-tắt nhóm → đo lại bề rộng rồi tính lại thu gọn.
    // Đo lại bề rộng nhóm CHỈ khi cấu trúc toolbar đổi (bật/tắt nhóm modes / ô tìm).
    // KHÔNG theo dõi labels()/viewMode(): [labels] ở bên gọi thường là object mới mỗi CD
    // → nếu track sẽ reset measured liên tục → reflow "hiện hết → đo → thu gọn" lặp lại
    // → thanh công cụ NHẢY GIẬT full↔thu. Đổi kích thước thật đã có ResizeObserver lo.
    effect(() => {
      this.showModes(); this.searchable();
      this.measured = false;
      queueMicrotask(() => this.zone.run(() => this.reflow()));
    });
  }

  /** Đo bề rộng THẬT từng nhóm khi tất cả đang hiện inline (dùng để tính thu gọn). */
  private measureAll(): void {
    const tb = this.toolbarRef()?.nativeElement; if (!tb) return;
    const q = (s: string) => (tb.querySelector(s) as HTMLElement | null)?.offsetWidth ?? 0;
    this.grpW = {
      orient: q('[data-grp="orient"]'), tools: q('[data-grp="tools"]'), zoom: q('[data-grp="zoom"]'),
      modes: q('[data-grp="modes"]'), search: q('[data-grp="search"]'), more: 40,
    };
    this.measured = true;
  }

  /** Tính nhóm nào phải thu vào "⋮" để thanh công cụ vừa 1 hàng (không rớt dòng). */
  protected reflow(): void {
    if (!this.showToolbar()) return;
    const tb = this.toolbarRef()?.nativeElement; if (!tb) return;
    const avail = tb.clientWidth;
    if (avail <= 0) return;
    if (!this.measured) {
      // Cần tất cả inline để đo — nếu đang thu gọn, hiện hết rồi đo ở khung hình kế.
      if (this.hidden().length) {
        this.hidden.set([]);
        this.zone.runOutsideAngular(() => requestAnimationFrame(() => this.zone.run(() => this.reflow())));
        return;
      }
      this.measureAll();
    }
    const GAP = 8, w = this.grpW;
    // Rất hẹp (nhãn modes + ⋮ + ô tìm tối thiểu không đủ chỗ) → thu nhãn modes thành icon.
    this.tight.set(this.showModes() && avail < w['modes'] + 150);
    const modesW = this.tight() ? 116 : w['modes']; // modes icon-only ~116px
    const base = (this.showModes() ? modesW + GAP : 0) + (this.searchable() ? w['search'] + GAP : 0);
    const optional = ['zoom', 'tools', 'orient'].filter((k) => w[k] > 0); // giữ lâu nhất: zoom → tools → orient
    const show = new Set(optional);
    const total = () => {
      let t = base;
      for (const k of show) t += w[k] + GAP;
      if (show.size < optional.length) t += w['more'] + GAP;
      return t;
    };
    for (const k of this.DROP) { if (total() <= avail - 2) break; show.delete(k); }
    const next = this.DROP.filter((k) => optional.includes(k) && !show.has(k));
    const cur = this.hidden();
    if (next.length !== cur.length || next.some((k, i) => k !== cur[i])) this.hidden.set(next);
    if (!next.length && this.moreOpen()) this.moreOpen.set(false);
  }

  /** Layout tidy — bề rộng cố định theo mode, CHIỀU CAO động theo nội dung node.
   *  Hàng dọc: y theo cao lớn nhất mỗi cấp; hàng ngang: y tích luỹ theo cao từng node. */
  protected readonly view = computed<OrgView>(() => {
    const roots = this.roots();
    const collapsed = this.collapsedSet();
    const counts = this.countMap();
    const horiz = this.orientation() === 'horizontal';
    const compact = this.compact();
    const mode = this.viewMode();
    const nw = mode === 'position' ? 300 : mode === 'department' ? (compact ? 196 : 232) : (compact ? 168 : 216);
    const gx = mode === 'position' ? 30 : (compact ? 20 : 34);
    const gy = mode === 'position' ? 40 : (compact ? 40 : 62);

    // Pass 1: cao + cấp mỗi node hiện; cao lớn nhất mỗi cấp (cho hàng dọc).
    const dims = new Map<string, { depth: number; h: number }>();
    const gather = (node: HrmOrgNode, depth: number) => {
      dims.set(node.id, { depth, h: this.heightOf(node, mode, compact) });
      if (!collapsed.has(node.id)) this.modeKids(node, mode).forEach((c) => gather(c, depth + 1));
    };
    roots.forEach((r) => gather(r, 0));
    const rowH: number[] = [];
    for (const d of dims.values()) rowH[d.depth] = Math.max(rowH[d.depth] ?? 0, d.h);
    const rowTop: number[] = [];
    let acc = 0;
    for (let d = 0; d < rowH.length; d++) { rowTop[d] = acc; acc += (rowH[d] ?? 0) + gy; }

    // Pass 2: đặt — trả về TÂM trục chính để cha canh giữa con.
    const laid = new Map<string, Laid>();
    let cx0 = 0, cy0 = 0;
    const place = (node: HrmOrgNode, depth: number): number => {
      const kids = collapsed.has(node.id) ? [] : this.modeKids(node, mode);
      const h = dims.get(node.id)!.h;
      let center: number;
      if (!kids.length) {
        if (horiz) { center = cy0 + h / 2; cy0 += h + gy; }
        else { center = cx0 + nw / 2; cx0 += nw + gx; }
      } else {
        const cs = kids.map((k) => place(k, depth + 1));
        center = (cs[0] + cs[cs.length - 1]) / 2;
      }
      laid.set(node.id, {
        node,
        x: horiz ? depth * (nw + gx) : center - nw / 2,
        y: horiz ? center - h / 2 : rowTop[depth],
        w: nw, h, depth,
        hasKids: (node.children?.length ?? 0) > 0,
        open: !collapsed.has(node.id),
        count: counts.get(node.id) ?? 0,
      });
      return center;
    };
    roots.forEach((r) => place(r, 0));

    const edges: Edge[] = [];
    const dotted: Edge[] = [];
    let w = 0, h = 0;
    for (const ln of laid.values()) {
      w = Math.max(w, ln.x + ln.w);
      h = Math.max(h, ln.y + ln.h);
      if (!collapsed.has(ln.node.id)) {
        for (const k of this.modeKids(ln.node, mode)) {
          const c = laid.get(k.id);
          if (c) edges.push({ d: this.elbow(ln, c, horiz), from: ln.node.id, to: c.node.id });
        }
      }
      for (const tid of (ln.node.dottedReports ?? [])) {
        const t = laid.get(tid);
        if (t) dotted.push({ d: this.curve(ln, t), from: ln.node.id, to: tid });
      }
    }
    return { nodes: [...laid.values()], edges, dotted, w, h, nw, nh: 0 };
  });

  /** Con hiển thị theo mode: Phòng ban chỉ node có unit, Vị trí chỉ node có position
   *  (ẩn node cá nhân không hợp thẻ mode). Nhân viên = tất cả. */
  private modeKids(node: HrmOrgNode, mode: HrmOrgViewMode): HrmOrgNode[] {
    const kids = node.children ?? [];
    if (mode === 'department') return kids.filter((k) => !!k.unit);
    if (mode === 'position') return kids.filter((k) => !!k.position);
    return kids;
  }

  /** Chiều cao thẻ theo mode + nội dung. */
  private heightOf(node: HrmOrgNode, mode: HrmOrgViewMode, compact: boolean): number {
    if (mode === 'position' && node.position) {
      const total = node.holders?.length ?? 0;
      const shown = Math.min(total, 5);
      const more = total > 5 ? 1 : 0;
      const hdr = 26 + (node.filled != null ? 18 : 0) + (node.hiring ? 30 : 0);
      return 28 + hdr + 10 + shown * 44 + more * 30;
    }
    if (mode === 'department' && node.unit) return compact ? 106 : 120;
    return compact ? 60 : 78;
  }

  private elbow(p: Laid, c: Laid, horiz: boolean): string {
    if (horiz) {
      const px = p.x + p.w, py = p.y + p.h / 2, cx = c.x, cy = c.y + c.h / 2, mx = (px + cx) / 2;
      return `M${px},${py} L${mx},${py} L${mx},${cy} L${cx},${cy}`;
    }
    const px = p.x + p.w / 2, py = p.y + p.h, cx = c.x + c.w / 2, cy = c.y, my = (py + cy) / 2;
    return `M${px},${py} L${px},${my} L${cx},${my} L${cx},${cy}`;
  }
  private curve(a: Laid, b: Laid): string {
    const ax = a.x + a.w / 2, ay = a.y + a.h / 2, bx = b.x + b.w / 2, by = b.y + b.h / 2;
    const my = Math.min(ay, by) - 44;
    return `M${ax},${ay} Q${(ax + bx) / 2},${my} ${bx},${by}`;
  }

  private readonly pathSet = computed<Set<string>>(() => {
    const s = new Set<string>();
    if (!this.highlightPath()) return s;
    let id = this.selectedId();
    if (!id) return s;
    const pm = this.parentMap();
    let guard = 0;
    while (id && guard++ < 200) { s.add(id); id = pm.get(id) ?? ''; }
    return s;
  });

  protected readonly matchIds = computed<string[]>(() => {
    const q = this.norm(this.searchQuery().trim());
    if (!q) return [];
    return this.view().nodes
      .filter((n) => this.norm(n.node.name).includes(q) || this.norm(n.node.title ?? '').includes(q))
      .map((n) => n.node.id);
  });
  protected currentMatchId(): string { return this.matchIds()[this.matchIdx()] ?? ''; }

  private norm(s: string): string {
    return (s || '').toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g, '').replace(/[\u0111]/g, 'd');
  }

  protected initialsOf(name: string): string {
    const n = (name || '').trim();
    if (!n) return '';
    const p = n.split(/\s+/);
    return ((p[0][0] ?? '') + (p.length > 1 ? p[p.length - 1][0] : '')).toUpperCase();
  }
  /** Hue 0..7 băm từ tên (đồng bộ hrm-avatar) — avatar chữ mỗi người 1 màu ổn định. */
  protected avatarHue(seed: string): number {
    let h = 0;
    for (let i = 0; i < (seed || '').length; i++) h = (h + seed.charCodeAt(i)) % 8;
    return h;
  }

  protected pick(node: HrmOrgNode): void {
    if (this.movedRecently) { this.movedRecently = false; return; }
    // Click lại node đang chọn → bỏ chọn (tắt tô tuyến báo cáo).
    this.selectedId.set(this.selectedId() === node.id ? '' : node.id);
    this.nodeClick.emit(node);
  }

  /** "23 nhân viên" — hậu tố từ labels (i18n). */
  protected headcountText(n: HrmOrgNode): string {
    const c = n.headcount ?? 0;
    const suf = this.labels().employees;
    return suf ? `${c} ${suf}` : `${c}`;
  }
  protected breakdownText(n: HrmOrgNode): string {
    return (n.breakdown ?? []).map((b) => `${b.count} ${b.type}`).join(', ');
  }
  protected holdersShown(n: HrmOrgNode): HrmOrgHolder[] {
    return (n.holders ?? []).slice(0, 5);
  }
  protected holdersMore(n: HrmOrgNode): number {
    return Math.max(0, (n.holders?.length ?? 0) - 5);
  }
  protected isDottedLit(e: Edge): boolean {
    const s = this.selectedId();
    return !!s && (e.from === s || e.to === s);
  }
  protected toggle(id: string): void {
    const s = new Set(this.collapsedSet());
    s.has(id) ? s.delete(id) : s.add(id);
    this.collapsedSet.set(s);
  }
  protected expandAll(): void { this.collapsedSet.set(new Set()); }
  protected collapseAll(): void {
    const s = new Set<string>();
    const walk = (n: HrmOrgNode) => { if (n.children?.length) s.add(n.id); n.children?.forEach(walk); };
    this.roots().forEach(walk);
    this.collapsedSet.set(s);
  }

  /** Badge hiển thị: ưu tiên badge caller, không có thì tổng quân số (nếu showCounts). */
  protected badgeOf(n: Laid): string | number | null {
    if (n.node.badge != null) return n.node.badge;
    if (this.showCounts() && n.count > 0) return n.count;
    return null;
  }
  protected isMatch(id: string): boolean { return this.matchIds().includes(id); }
  protected isDim(id: string): boolean {
    const ps = this.pathSet();
    return ps.size > 0 && !ps.has(id);
  }
  protected isEdgeDim(e: Edge): boolean {
    const ps = this.pathSet();
    return ps.size > 0 && !(ps.has(e.from) && ps.has(e.to));
  }
  protected isEdgeLit(e: Edge): boolean {
    const ps = this.pathSet();
    return ps.size > 0 && ps.has(e.from) && ps.has(e.to);
  }

  protected onSearch(e: Event): void {
    this.searchQuery.set((e.target as HTMLInputElement).value);
    this.matchIdx.set(0);
    setTimeout(() => this.centerCurrentMatch());
  }
  protected clearSearch(): void { this.searchQuery.set(''); this.matchIdx.set(0); }
  protected nextMatch(): void {
    const n = this.matchIds().length; if (!n) return;
    this.matchIdx.set((this.matchIdx() + 1) % n);
    this.centerCurrentMatch();
  }
  protected prevMatch(): void {
    const n = this.matchIds().length; if (!n) return;
    this.matchIdx.set((this.matchIdx() - 1 + n) % n);
    this.centerCurrentMatch();
  }
  private centerCurrentMatch(): void {
    const id = this.currentMatchId();
    if (id) this.centerOn(id);
  }
  private centerOn(id: string): void {
    const vp = this.vp()?.nativeElement; if (!vp) return;
    const v = this.view();
    const ln = v.nodes.find((n) => n.node.id === id); if (!ln) return;
    const z = this.zoom();
    this.pan.set({
      x: vp.clientWidth / 2 - (ln.x + ln.w / 2) * z,
      y: vp.clientHeight / 2 - (ln.y + ln.h / 2) * z,
    });
  }

  /** Bấm-đúp node có con → focus (xem riêng nhánh). */
  protected onDblNode(node: HrmOrgNode): void {
    if (!this.focusable() || !node.children?.length) return;
    this.focusId.set(node.id);
    this.focusChange.emit(node.id);
    setTimeout(() => this.fit());
  }
  protected resetFocus(): void {
    this.focusId.set('');
    this.focusChange.emit('');
    setTimeout(() => this.fit());
  }

  /** Nút zoom → phóng quanh tâm khung. */
  protected zoomBy(f: number): void {
    const vp = this.vp()?.nativeElement;
    if (vp) this.zoomAt(f, vp.clientWidth / 2, vp.clientHeight / 2);
    else this.zoom.set(Math.min(2, Math.max(0.35, this.zoom() * f)));
  }
  /** Phóng quanh 1 điểm (cx,cy) trong khung nhìn — giữ điểm đó cố định dưới con trỏ. */
  private zoomAt(f: number, cx: number, cy: number): void {
    const z = this.zoom();
    const z2 = Math.min(2, Math.max(0.35, z * f));
    if (z2 === z) return;
    const p = this.pan();
    this.pan.set({ x: cx - (cx - p.x) * (z2 / z), y: cy - (cy - p.y) * (z2 / z) });
    this.zoom.set(z2);
  }
  protected fit(): void {
    const vp = this.vp()?.nativeElement;
    if (!vp) return;
    const v = this.view();
    const s = Math.min(vp.clientWidth / (v.w || 1), vp.clientHeight / (v.h || 1), 1) * 0.92;
    this.zoom.set(s);
    this.pan.set({ x: Math.max(16, (vp.clientWidth - v.w * s) / 2), y: 20 });
  }

  protected onDown(e: PointerEvent): void {
    if (!this.zoomable()) return;
    this.drag = { x: e.clientX, y: e.clientY, px: this.pan().x, py: this.pan().y, moved: false };
    (e.target as Element).setPointerCapture?.(e.pointerId);
  }
  protected onMove(e: PointerEvent): void {
    if (!this.drag) return;
    const dx = e.clientX - this.drag.x, dy = e.clientY - this.drag.y;
    if (Math.abs(dx) > 3 || Math.abs(dy) > 3) this.drag.moved = true;
    // Bật cờ dragging → tắt transition để kéo bám tay (chỉ zoom/nhảy mới mượt).
    if (this.drag.moved && !this.dragging()) this.dragging.set(true);
    this.pan.set({ x: this.drag.px + dx, y: this.drag.py + dy });
  }
  protected onUp(_e: PointerEvent): void {
    // Kéo → chặn click node phát sinh ngay sau (pointerup rồi mới tới click).
    this.movedRecently = !!this.drag?.moved;
    this.drag = null;
    this.dragging.set(false);
  }
  protected onWheel(e: WheelEvent): void {
    if (!this.zoomable()) return;
    e.preventDefault();
    const vp = this.vp()?.nativeElement;
    if (!vp) return;
    const r = vp.getBoundingClientRect();
    // Zoom quanh vị trí con trỏ; bước nhẹ + transition .34s cho mượt.
    this.zoomAt(e.deltaY < 0 ? 1.05 : 0.952, e.clientX - r.left, e.clientY - r.top);
  }
}
